import type { Vec3 } from '../contracts/math';
import type { InputAction, InputSnapshot, PointerSnapshot } from '../input/InputManager';
import type { CameraCollisionOptions, CameraRaycaster } from './CameraCollision';
import { CameraController } from './CameraController';
import type { CameraMode, CameraModeSettings, HoleFraming } from './CameraModes';
import { cameraModeSettings, isCameraMode, overviewPose, yawTowards } from './CameraModes';
import type { CameraPose } from './CameraPose';
import { createCameraPose } from './CameraPose';
import type { CameraTransitionOptions } from './CameraTransition';
import { SmoothCameraRig } from './SmoothCameraRig';

export interface CameraDirectorOptions {
  raycaster?: CameraRaycaster;
  collision?: CameraCollisionOptions;
  /** Per mode tuning overrides, e.g. a closer aim camera for a specific game. */
  modes?: Partial<Record<CameraMode, Partial<CameraModeSettings>>>;
  focus?: Vec3;
  framing?: HoleFraming;
  initialMode?: CameraMode;
  /** Radians per second the overview drifts around the hole. */
  overviewSpin?: number;
  minDistance?: number;
  maxDistance?: number;
}

export interface CameraModeChangeOptions extends CameraTransitionOptions {
  /** Cut instead of blending; only the first frame of a match should need it. */
  immediate?: boolean;
  /** Restart the blend even when the mode does not change. */
  force?: boolean;
  /** Re-aim the orbit before the blend starts. */
  yaw?: number;
}

const PAN_ACTIONS: readonly InputAction[] = ['camera-forward', 'camera-backward', 'camera-left', 'camera-right'];
const DEFAULT_OVERVIEW_SPIN = 0.12;
const OVERVIEW_ORBIT_SENSITIVITY = 0.004;

/**
 * Camera mode machine on top of the orbit controller and the smoothing rig.
 *
 * Aim sits behind the ball, follow trails it while it rolls, overview shows the
 * whole hole before the first shot and free lets the player wander off with WASD.
 * Every switch and every new focus goes through a timed transition and springs,
 * so the camera glides to its new pose over several frames instead of cutting.
 */
export class CameraDirector {
  private readonly controller: CameraController;
  private readonly rig: SmoothCameraRig;
  private readonly overrides: Partial<Record<CameraMode, Partial<CameraModeSettings>>>;
  private readonly spin: number;
  private currentMode: CameraMode;
  private focusPoint: Vec3;
  private framing?: HoleFraming;
  private overviewYaw: number;

  constructor(options: CameraDirectorOptions = {}) {
    this.overrides = options.modes ?? {};
    this.spin = Number.isFinite(options.overviewSpin) ? (options.overviewSpin as number) : DEFAULT_OVERVIEW_SPIN;
    this.currentMode = options.initialMode ?? 'aim';
    this.focusPoint = copy(options.focus ?? { x: 0, y: 0, z: 0 });
    this.framing = options.framing;

    const settings = this.settings();
    this.controller = new CameraController({
      target: this.aimTarget(settings),
      yaw: this.framing ? yawTowards(this.focusPoint, this.framing.cup) : undefined,
      pitch: settings.pitch,
      distance: settings.distance,
      minDistance: options.minDistance ?? 2,
      maxDistance: options.maxDistance ?? 60,
    });
    this.overviewYaw = this.framing ? yawTowards(this.framing.spawn, this.framing.cup) : this.controller.state.yaw;
    this.rig = new SmoothCameraRig(this.desiredPose(settings), {
      positionSmoothTime: settings.positionSmoothTime,
      targetSmoothTime: settings.targetSmoothTime,
      raycaster: options.raycaster,
      collision: options.collision,
    });
  }

  get mode(): CameraMode {
    return this.currentMode;
  }

  /** Smoothed pose of the last update; what the renderer should display. */
  get pose(): CameraPose {
    return this.rig.current;
  }

  /** Orbit yaw the aiming code shoots along; never smoothed, so shots stay exact. */
  get yaw(): number {
    return this.currentMode === 'overview' ? this.overviewYaw : this.controller.state.yaw;
  }

  get isTransitioning(): boolean {
    return this.rig.transition.isActive;
  }

  get focus(): Vec3 {
    return copy(this.focusPoint);
  }

  /** Hole geometry the overview frames and the recentre logic aims at. */
  setFraming(framing: HoleFraming): void {
    this.framing = framing;
    if (this.currentMode === 'overview') this.overviewYaw = yawTowards(framing.spawn, framing.cup);
  }

  /** Point the camera tracks; called every frame with the live ball position. */
  setFocus(position: Vec3): void {
    if (!isFiniteVector(position)) return;
    this.focusPoint = copy(position);
  }

  setMode(mode: CameraMode, options: CameraModeChangeOptions = {}): boolean {
    if (!isCameraMode(mode)) return false;
    if (mode === this.currentMode && options.force !== true) return false;
    this.currentMode = mode;
    const settings = this.settings();

    if (mode === 'overview') {
      this.overviewYaw = options.yaw ?? (this.framing ? yawTowards(this.framing.spawn, this.framing.cup) : this.overviewYaw);
    } else {
      this.controller.setOrbit(options.yaw ?? this.controller.state.yaw, settings.pitch, settings.distance);
      if (mode !== 'free') this.controller.setTarget(this.aimTarget(settings));
    }

    if (options.immediate) {
      this.rig.snapTo(this.desiredPose(settings));
    } else {
      this.rig.transitionTo({
        durationSeconds: options.durationSeconds ?? settings.transitionSeconds,
        easing: options.easing ?? settings.easing,
      });
    }
    return true;
  }

  /** Moves the focus and glides the camera behind it, facing the cup when known. */
  focusOn(position: Vec3, options: CameraModeChangeOptions & { mode?: CameraMode } = {}): void {
    this.setFocus(position);
    const yaw = options.yaw ?? (this.framing ? yawTowards(this.focusPoint, this.framing.cup) : undefined);
    this.setMode(options.mode ?? 'aim', { ...options, yaw, force: true });
  }

  /** The R key: leave free or overview behind and slide back to the ball. */
  recenter(options: CameraModeChangeOptions & { mode?: CameraMode } = {}): void {
    this.focusOn(this.focusPoint, options);
  }

  update(deltaSeconds: number, input?: InputSnapshot): CameraPose {
    const step = Number.isFinite(deltaSeconds) && deltaSeconds > 0 ? deltaSeconds : 0;
    if (input) this.consumeInput(input);

    const settings = this.settings();
    this.rig.configure({
      positionSmoothTime: settings.positionSmoothTime,
      targetSmoothTime: settings.targetSmoothTime,
    });

    if (this.currentMode === 'overview') {
      this.overviewYaw += this.spin * step;
    } else {
      if (this.currentMode !== 'free') this.controller.setTarget(this.aimTarget(settings));
      this.controller.update(step, input ? filterInput(input, settings) : undefined);
    }

    return this.rig.update(step, this.desiredPose(settings));
  }

  private consumeInput(input: InputSnapshot): void {
    if (input.wasPressed('camera-reset')) {
      this.recenter();
      return;
    }
    if (this.currentMode !== 'free' && PAN_ACTIONS.some((action) => input.isDown(action))) {
      this.setMode('free');
    }
  }

  private settings(): CameraModeSettings {
    return cameraModeSettings(this.currentMode, this.overrides[this.currentMode]);
  }

  private aimTarget(settings: CameraModeSettings): Vec3 {
    return { x: this.focusPoint.x, y: this.focusPoint.y + settings.targetHeight, z: this.focusPoint.z };
  }

  private desiredPose(settings: CameraModeSettings): CameraPose {
    if (this.currentMode === 'overview' && this.framing) {
      return overviewPose(this.framing, { yaw: this.overviewYaw, pitch: settings.pitch, fov: settings.fov });
    }
    const state = this.controller.state;
    return createCameraPose(state.position, state.target, settings.fov);
  }
}

/** Hides the reset key from the orbit controller and gates orbit/pan per mode. */
function filterInput(input: InputSnapshot, settings: CameraModeSettings): InputSnapshot {
  const pointer: PointerSnapshot = settings.allowOrbit
    ? input.pointer
    : { ...input.pointer, deltaX: 0, deltaY: 0, wheel: 0 };
  return {
    pointer,
    isDown: (action) => (!settings.allowPan && PAN_ACTIONS.includes(action) ? false : input.isDown(action)),
    wasPressed: (action) => (action === 'camera-reset' ? false : input.wasPressed(action)),
    wasReleased: (action) => input.wasReleased(action),
  };
}

function copy(value: Vec3): Vec3 {
  return { x: value.x, y: value.y, z: value.z };
}

function isFiniteVector(value: Vec3): boolean {
  return Number.isFinite(value.x) && Number.isFinite(value.y) && Number.isFinite(value.z);
}

export { OVERVIEW_ORBIT_SENSITIVITY };
